import functools

# Sentinel for calls whose arguments cannot be hashed: they run but are
# neither cached nor counted as hits/misses.
_UNCACHEABLE = object()


def _key(args, kwargs):
    # (positional args, keyword pairs) — keywords participate in the key so
    # distance(a, b, units="mi") is a distinct entry from distance(a, b),
    # while dict ordering of identical keywords does not create new entries
    # (kwargs preserves call order; same call text always yields same key).
    try:
        return (args, tuple(kwargs.items()))
    except TypeError:
        return _UNCACHEABLE


def memoize(fn):
    cache = {}
    stats = {"hits": 0, "misses": 0}

    @functools.wraps(fn)
    def wrapper(*args, **kwargs):
        key = _key(args, kwargs)
        if key is not _UNCACHEABLE:
            if key in cache:
                stats["hits"] += 1
                return cache[key]
            stats["misses"] += 1
            result = fn(*args, **kwargs)
            cache[key] = result
            return result
        return fn(*args, **kwargs)

    wrapper.cache_info = lambda: dict(stats, size=len(cache))

    def cache_clear():
        cache.clear()
        stats.update(hits=0, misses=0)

    wrapper.cache_clear = cache_clear
    return wrapper
