import functools


def memoize(fn):
    cache = {}
    stats = {"hits": 0, "misses": 0}
    try:
        sig = inspect.signature(fn)
    except (TypeError, ValueError):
        sig = None

    @functools.wraps(fn)
    def wrapper(*args, **kwargs):
        # Build a cache key from the *bound* arguments so that:
        #  - positional and keyword arguments both count:
        #    f(a, b, "mi") is a different key than f(a, b, units="mi");
        #  - keyword order is irrelevant: f(x=1, y=2) is f(y=2, x=1);
        #  - calls with unhashable arguments (e.g. a list of waypoints)
        #    still work, they just aren't cached.
        key = None
        if sig is not None:
            try:
                bound = sig.bind_partial(*args, **kwargs)
                key = tuple(sorted(bound.arguments.items()))
            except TypeError:
                key = None
        else:
            key = (args, tuple(sorted(kwargs.items())))

        try:
            hash(key)
        except TypeError:
            key = None

        if key is not None:
            if key in cache:
                stats["hits"] += 1
                return cache[key]
            stats["misses"] += 1
            result = fn(*args, **kwargs)
            cache[key] = result
            return result
        return fn(*args, **kwargs)

    wrapper.cache_info = lambda: dict(stats, size=len(cache))

    def cache_clear():
        cache.clear()
        stats.update(hits=0, misses=0)

    wrapper.cache_clear = cache_clear
    return wrapper


